import{_ as t,o as n,c as o,j as e,a as r}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xuehui-tiwen/108-思考过快.md","filePath":"books/xuehui-tiwen/108-思考过快.md","lastUpdated":1794316978000}'),s={name:"books/xuehui-tiwen/108-思考过快.md"};function l(i,a,d,p,u,c){return n(),o("div",null,[...a[0]||(a[0]=[e("h2",{id:"思考过快",tabindex:"-1"},[r("思考过快 "),e("a",{class:"header-anchor",href:"#思考过快","aria-label":'Permalink to "思考过快"'},"​")],-1),e("p",null,"我们时刻都在思考。我们的大脑几乎总在不间断地处理周围世界的信息。无论我们在决定早晨出门该穿哪件衬衫，还是在决定该信仰哪一个宗教，我们都在不断地思考。",-1),e("p",null,"我们的大脑能够很快思考。但幸运的是，我们的大脑还有另外一种能力，一种被卡尼曼称为“慢思考”的能力。后一种思考方式，或者说“系统2思维”，正是本书关注的重点。",-1),e("p",null,"所谓慢思考，就是使用我们的大脑来吸收和理性评估别人与我们交流的内容。如果必须要用两个字来概括本书传递的信息，那就是在你思考重大事情的时候一定要“放慢”。",-1),e("p",null,"相反，我们的“系统1思维”只是根据手边既有的一点信息，不做任何深刻、全面的思考就仓促做出决断。如果不对我们所做的决定进行慢速、有条理的思考，那么我们犯错的概率就会大大增加。",-1),e("p",null,"但是，我们也无须绝望。“系统2思维”有能力否决“系统1思维”所做的决定。我们的任务就在于训练“系统2思维”不要依赖“系统1思维”来做决定。依赖“系统1思维”固然容易，可以节省很多精力，使我们无须对自身的认识做大量分析和评估的工作。但是，如果依赖“系统1思维”，我们就会牺牲准确和智慧以换取速度。我们要培养的习惯，是常常问一问自己：“我到底依赖什么来支持我的信念和结论？”",-1)])])}const f=t(s,[["render",l]]);export{m as __pageData,f as default};
